function renderCodeDocs(){const box=$('#codeDocsIssues');if(!box)return;const r=calcCodeDocs();if(!r){$('#codeDocsScore').textContent='—';box.innerHTML='<div class="analysis-empty">Analiza una carpeta, ZIP o repositorio GitHub para habilitar esta auditoría.</div>';return}$('#codeDocsScore').textContent=r.score+'/100';box.innerHTML=(r.items.length?r.items:[{severity:'COHERENTE',text:'No se detectan contradicciones en las reglas disponibles.',type:'good'}]).map(x=>`<div class="issue ${x.type||'warn'}"><div><span class="severity">${esc(x.severity)}</span><p>${esc(x.text)}</p></div></div>`).join('');if(r.coverage<70)box.insertAdjacentHTML('beforeend',`<div class="issue warn"><div><span class="severity">COBERTURA ${r.coverage}%</span><p>Hay capacidades detectadas en código que todavía no aparecen suficientemente en la documentación.</p></div></div>`)}
