 if(hasName(/(^|\/)pnpm-lock\.yaml$/i))e.packageManager='pnpm';else if(hasName(/(^|\/)yarn\.lock$/i))e.packageManager='Yarn';else if(hasName(/(^|\/)package-lock\.json$/i))e.packageManager='npm';else if(pkgText)e.packageManager='npm / compatible';
 e.repo.readme=hasName(/(^|\/)README\.md$/i);e.repo.license=hasName(/(^|\/)LICENSE(?:\.[^/]+)?$/i);e.repo.gitignore=hasName(/(^|\/)\.gitignore$/i);e.repo.workflows=names.filter(n=>/(^|\/)\.github\/workflows\/[^/]+\.ya?ml$/i.test(n)).length;e.repo.tests=e.repo.tests||names.some(n=>/(?:^|\/)(?:__tests__\/|[^/]+\.(?:test|spec)\.[a-z]+$)/i.test(n));e.repo.docs=names.filter(n=>/(^|\/)docs?\/.+\.md$/i.test(n)).length;
 for(const [n,c] of Object.entries(files)){if(/\.html?$/i.test(n)){e.pages.push(n);const title=c.match(/<title[^>]*>([^<]+)<\/title>/i)?.[1]?.trim();if(title)e.features.push(`Título HTML: ${title}`)}if(/manifest\.(webmanifest|json)$/i.test(n)){e.pwa.manifest=true;try{const m=JSON.parse(c);if(m.name)e.features.push(`Manifest name: ${m.name}`)}catch{}}if(/serviceWorker\.register|navigator\.serviceWorker/i.test(c))e.pwa.serviceWorker=true;if(/indexedDB/i.test(c)&&!e.storage.includes('IndexedDB'))e.storage.push('IndexedDB');if(/localStorage/i.test(c)&&!e.storage.includes('localStorage'))e.storage.push('localStorage');for(const [label,re] of [['File System Access',/show(Open|Save|Directory)FilePicker/i],['Fetch API',/\bfetch\s*\(/],['Compression Streams',/(CompressionStream|DecompressionStream)/],['Web Worker',/new\s+Worker\s*\(/],['WebAssembly',/WebAssembly\./],['Canvas',/getContext\s*\(\s*['"]2d['"]/],['Clipboard API',/navigator\.clipboard/]])if(re.test(c)&&!e.apis.includes(label))e.apis.push(label);e.todoCount+=(c.match(/\b(?:TODO|FIXME|HACK|XXX)\b/g)||[]).length;for(const m of c.matchAll(/https?:\/\/([^/'"\s)]+)/g))if(!e.externalHosts.includes(m[1]))e.externalHosts.push(m[1])}
