async function analyzeFilesList(list,label='Carpeta importada'){const files={},names=[];let total=0,count=0;for(const f of list){if(count++>=MAX_ENTRIES)break;const n=f.webkitRelativePath||f.name;names.push(n);if(canReadText(n,f.size)&&total+f.size<=MAX_TOTAL_TEXT){files[n]=await f.text();total+=f.size}}const e=deriveEvidence(files,label,names);if(count>MAX_ENTRIES)e.warnings.push(`Se alcanzó el límite de ${MAX_ENTRIES} entradas.`);if(total>=MAX_TOTAL_TEXT)e.warnings.push('Se alcanzó el límite de lectura de texto de 10 MB.');showEvidence(e)}
