function searchJs(index){return `window.MD_FORGE_SEARCH=${JSON.stringify(index)};(function(){const q=document.getElementById('siteSearch'),r=document.getElementById('siteSearchResults'),base=window.MD_FORGE_BASE||'';if(!q||!r)return;q.addEventListener('input',()=>{const s=q.value.trim().toLowerCase();if(!s){r.className='search-results';r.innerHTML='';return}const hits=window.MD_FORGE_SEARCH.filter(x=>(x.title+' '+x.text).toLowerCase().includes(s)).slice(0,12);r.innerHTML=hits.map(x=>'<a href="'+base+x.url+'"><strong>'+x.title.replace(/[<>&]/g,'')+'</strong><small>'+x.text.slice(0,100).replace(/[<>&]/g,'')+'</small></a>').join('')||'<small>Sin resultados</small>';r.className='search-results show'});document.addEventListener('click',e=>{if(e.target!==q&&!r.contains(e.target))r.className='search-results'})})();`}
function stripMarkdown(md){return String(md).replace(/```[\s\S]*?```/g,' ').replace(/!\[[^\]]*\]\([^)]+\)/g,' ').replace(/\[([^\]]+)\]\([^)]+\)/g,'$1').replace(/[#>*_`|~-]/g,' ').replace(/\s+/g,' ').trim()}
function navGroup(file){const d=dirName(file);return d?d.split('/')[0].replace(/[-_]/g,' '):'General'}
function siteBreadcrumb(file,siteMap){if(file===state.site.homeDoc)return'';const outDir=dirName(siteMap[file]),home=relativePath(outDir,'index.html'),bits=normalizePathLoose(file).split('/');bits.pop();return `<nav class="breadcrumb" aria-label="Breadcrumb"><a href="${esc(home)}">Inicio</a>${bits.map(x=>` <span>›</span> <span>${esc(x)}</span>`).join('')} <span>›</span> <span>${esc(titleOf(state.files[file],file))}</span></nav>`}
function sitePageNav(index,pages){const prev=pages[index-1],next=pages[index+1],outDir=dirName(pages[index].out);return `<nav class="page-nav" aria-label="Navegación entre páginas">${prev?`<a href="${esc(relativePath(outDir,prev.out))}"><small>← Anterior</small><strong>${esc(prev.title)}</strong></a>`:'<span></span>'}${next?`<a href="${esc(relativePath(outDir,next.out))}"><small>Siguiente →</small><strong>${esc(next.title)}</strong></a>`:''}</nav>`}
async function buildSiteEntries(){state.site={...state.site,title:$('#siteTitle').value.trim()||state.name,description:$('#siteDescription').value.trim()||state.description,theme:$('#siteTheme').value,homeDoc:$('#siteHomeDoc').value||state.site.homeDoc,baseUrl:$('#siteBaseUrl').value.trim(),logo:$('#siteLogoSelect').value,footer:$('#siteFooter').value.trim()||'Documentación generada con MD Forge 404'};const docsOrder=orderedSiteDocs();if(!docsOrder.includes(state.site.homeDoc))state.site.homeDoc=docsOrder.includes('README.md')?'README.md':docsOrder[0];save(false);const docs=Object.fromEntries(docsOrder.map(n=>[n,state.files[n]])),siteMap={};for(const n of docsOrder)siteMap[n]=siteOutputPath(n,state.site.homeDoc);const pages=docsOrder.map(file=>({file,out:siteMap[file],title:titleOf(docs[file],file),text:stripMarkdown(docs[file])})),entries={'assets/site.css':siteCss(state.site.theme)},searchIndex=pages.map(p=>({title:p.title,url:p.out,text:p.text.slice(0,700)}));entries['assets/search.js']=searchJs(searchIndex);for(let i=0;i<pages.length;i++){const p=pages[i],outDir=dirName(p.out),root=outDir?relativePath(outDir,'')+'/':'',css=relativePath(outDir,'assets/site.css'),js=relativePath(outDir,'assets/search.js'),home=relativePath(outDir,'index.html');let lastGroup='',nav='';for(const x of pages){const group=navGroup(x.file);if(group!==lastGroup){nav+=`<div class="nav-group">${esc(group)}</div>`;lastGroup=group}nav+=`<a class="${x.file===p.file?'active':''}" href="${esc(relativePath(outDir,x.out))}">${esc(x.title)}</a>`}const body=render(docs[p.file],{linkResolver:siteResolver(p.file,siteMap),imageResolver:siteImageResolver(p.file,siteMap)}),logo=state.site.logo&&state.assets[state.site.logo]?`<img class="site-logo" src="${esc(relativePath(outDir,state.site.logo))}" alt="">`:'';const canonical=validBaseUrl(state.site.baseUrl)?`<link rel="canonical" href="${esc(new URL(p.out,validBaseUrl(state.site.baseUrl)).href)}">`:'';const favicon=state.site.logo&&state.assets[state.site.logo]?`<link rel="icon" href="${esc(relativePath(outDir,state.site.logo))}">`:'';entries[p.out]=`<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="${esc(state.site.description)}"><title>${esc(p.title)} · ${esc(state.site.title)}</title>${canonical}${favicon}<link rel="stylesheet" href="${esc(css)}"></head><body><header class="top"><a class="brand-link" href="${esc(home)}">${logo}<strong>${esc(state.site.title)}</strong></a><input id="siteSearch" placeholder="Buscar documentación…" aria-label="Buscar documentación"><div id="siteSearchResults" class="search-results"></div></header><div class="layout"><aside>${nav}</aside><main><article class="doc">${siteBreadcrumb(p.file,siteMap)}${body}${sitePageNav(i,pages)}</article><footer class="site-footer">${esc(state.site.footer)}</footer></main></div><script>window.MD_FORGE_BASE=${JSON.stringify(root)}</script><script src="${esc(js)}"></script></body></html>`}
 for(const path of Object.keys(state.assets||{})){const blob=await getAssetBlob(path);if(blob)entries[path]=blob}entries['404.html']=`<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>404 · ${esc(state.site.title)}</title><link rel="stylesheet" href="assets/site.css"></head><body><main><article class="doc"><h1>404</h1><p>La página solicitada no existe.</p><p><a href="index.html">Volver a la documentación</a></p></article></main></body></html>`;entries['.nojekyll']='';const base=validBaseUrl(state.site.baseUrl);if(base){entries['sitemap.xml']=`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${pages.map(p=>`<url><loc>${esc(new URL(p.out,base).href)}</loc></url>`).join('')}</urlset>`;entries['robots.txt']=`User-agent: *\nAllow: /\nSitemap: ${new URL('sitemap.xml',base).href}\n`}return entries}
async function exportSite(){try{const entries=await buildSiteEntries(),blob=await zipStoreRaw(entries),base=state.name.replace(/[^a-z0-9_-]+/gi,'-')||'documentation';download(blob,base+'-docs-site.zip');toast('Site Builder 2.0 exportado')}catch(err){alert(err.message||String(err))}}
async function previewSite(){const docs=orderedSiteDocs();if(!docs.length)return alert('No hay documentos Markdown.');const file=state.files[current]?current:(state.site.homeDoc||docs[0]),md=state.files[file]||'',title=titleOf(md,file),css=siteCss($('#siteTheme').value),html=`<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${esc(title)}</title><style>${css}</style></head><body><header class="top"><strong>${esc($('#siteTitle').value||state.name)}</strong></header><main><article class="doc">${render(md)}</article></main><footer class="site-footer">${esc($('#siteFooter').value||'')}</footer></body></html>`,blob=new Blob([html],{type:'text/html'}),url=URL.createObjectURL(blob),w=window.open(url,'_blank','noopener');if(!w)toast('El navegador bloqueó la vista previa emergente');setTimeout(()=>URL.revokeObjectURL(url),30000)}
function renderSiteNavOrder(){const box=$('#siteNavOrder');if(!box)return;const order=orderedSiteDocs();box.innerHTML=order.map((f,i)=>`<div class="site-nav-row"><span>${esc(f)}</span><div class="site-nav-actions"><button data-nav-up="${i}" ${i===0?'disabled':''}>↑</button><button data-nav-down="${i}" ${i===order.length-1?'disabled':''}>↓</button></div></div>`).join('');$$('[data-nav-up]').forEach(b=>b.onclick=()=>moveSiteNav(Number(b.dataset.navUp),-1));$$('[data-nav-down]').forEach(b=>b.onclick=()=>moveSiteNav(Number(b.dataset.navDown),1))}
function moveSiteNav(i,d){const order=orderedSiteDocs(),j=i+d;if(j<0||j>=order.length)return;[order[i],order[j]]=[order[j],order[i]];state.site.navOrder=order;save(false);renderSiteNavOrder()}
function renderBuild(){if(!$('#sitePageCount'))return;const docs=orderedSiteDocs(),assets=Object.keys(state.assets||{});$('#sitePageCount').textContent=`${docs.length} página${docs.length===1?'':'s'}`;$('#assetBuildCount').textContent=`${assets.length} asset${assets.length===1?'':'s'}`;$('#siteTitle').value=state.site?.title||state.name;$('#siteDescription').value=state.site?.description||state.description;$('#siteTheme').value=state.site?.theme||'auto';$('#siteHomeDoc').innerHTML=docs.map(x=>`<option value="${esc(x)}" ${x===state.site.homeDoc?'selected':''}>${esc(x)}</option>`).join('');$('#siteBaseUrl').value=state.site?.baseUrl||'';$('#siteFooter').value=state.site?.footer||'';$('#siteLogoSelect').innerHTML='<option value="">Sin logo</option>'+assets.map(x=>`<option value="${esc(x)}" ${x===state.site.logo?'selected':''}>${esc(x)}</option>`).join('');renderSiteNavOrder()}

function renderPublish(){const checks=[['README','Obligatorio',!!state.files['README.md']],['Changelog','Recomendado',!!state.files['CHANGELOG.md']],['Security','Recomendado',!!state.files['SECURITY.md']],['Contributing','Recomendado',!!state.files['CONTRIBUTING.md']],['Code of Conduct','Opcional',!!state.files['CODE_OF_CONDUCT.md']],['Repositorio vinculado','Recomendado',!!state.repository],['Quality Workflow','Opcional',!!state.extras?.['.github/workflows/documentation-quality.yml']]];const weights=[22,14,14,12,8,16,14],score=checks.reduce((a,x,i)=>a+(x[2]?weights[i]:0),0);$('#githubScore').textContent=score+'%';$('#githubChecklist').innerHTML=checks.map(([l,k,ok])=>`<div class="check-item"><span>${esc(l)}<small class="muted"> · ${esc(k)}</small></span><span class="${ok?'good':'missing'}">${ok?'✓ Listo':'○ Falta'}</span></div>`).join('')}

