 {label:'Cambiar workspace',hint:'Mis proyectos',run:()=>gotoPage('home')},{label:'Analizar un proyecto',hint:'Carpeta o ZIP',run:()=>gotoPage('project')},{label:'Analizar repositorio GitHub',hint:'Público · sin token',run:()=>gotoPage('github')},{label:'README Wizard',hint:'Paso a paso',run:openWizard},{label:'Buscar en todo el proyecto',hint:'Ctrl+Shift+F',run:openSearch},{label:'Abrir editor',hint:'Ctrl+E',run:()=>gotoPage('editor')},{label:'Ejecutar MD Doctor Pro',hint:'Ctrl+D',run:()=>gotoPage('doctor')},{label:'Auditar código ↔ documentación',hint:'Evidencias',run:runCodeDocs},{label:'Ver historial',hint:'Snapshots y Diff',run:()=>openHistory()},{label:'Gestionar assets',hint:'Imágenes',run:()=>openAssetManager()},{label:'Generar Documentation Pack',hint:'Docs faltantes',run:openDocsPack},{label:'Construir sitio de documentación',hint:'Site Builder 2.0',run:()=>gotoPage('build')},{label:'Generar GitHub Quality Workflow',hint:'Automatización',run:generateQualityWorkflow},{label:'Crear README',hint:'Plantilla',run:()=>{applyTemplate('README.md');gotoPage('editor')}},{label:'Crear CHANGELOG',hint:'Plantilla',run:()=>{applyTemplate('CHANGELOG.md');gotoPage('editor')}},{label:'Exportar documentación ZIP',hint:'Descargar',run:exportProjectZip}
