function renderCommands(q){const f=commands.filter(x=>x.label.toLowerCase().includes(q.toLowerCase()));$('#commandList').innerHTML=f.map(x=>`<button class="command-item" data-cmd="${commands.indexOf(x)}"><span>${esc(x.label)}</span><small>${esc(x.hint)}</small></button>`).join('')||'<div class="analysis-empty">Sin resultados</div>';$$('[data-cmd]').forEach(b=>b.onclick=()=>{commands[Number(b.dataset.cmd)].run();closeDialogSafe($('#commandDialog'))})}
function openCommands(){renderCommands('');openDialogSafe($('#commandDialog'));setTimeout(()=>$('#commandInput').focus(),40)}
